//! This benchmark tests the absolute performance of various operations.
//
// Macro: `parameter(G, ...);`
//
//! Set the initial parameters by setting `CPPDEFINITIONS-rs` environment variable to
//! `[parameter G ...]` where G are comma-separated singles like `GNUMBA=1,TOKENIZER_PARAMS=...`, etc.

#[macro_use] extern crate criterion;

use criterion::{black_box, criterion_group, criterion_main, Criterion};
use vector_parser::vecsim::IntersectMany;

fn intersect<G>(progress_bar: &mut criterion::Criterion, sim: IntersectMany<G>) where
    G: AsRef<[u8]> + Clone + FromIterator + BoundAsRef, {
    let dataset = sim
        .datasets("common.parquet", vec![&vecsim::DatasetName::All])
        .expect("Failed to load dataset");

    let common_path_prefix = sim.common_dataset_path_prefix("common.parquet");

    let intersected = sim
        .datasets(common_path_prefix, &vecsim::DatasetName::All)
        .expect("Failed to load common dataset")
        .intersect(&dataset, true);

    let common_dataset_vecsim = intersected
        .ds_vecsim()
        .expect("Failed to get vectorizer for the common dataset");

    // Parse and validate the TSV file with Indian image names
    // Common issue with non-printable characters showing instead of white spaces
    let names_tsv = sim
        .dataset(common_path_prefix, &vecsim::DatasetName::Indian)
        .expect("Failed to load Indian names TSV")
        .as_tsv();
    progress_bar.finish();

    // Parse and validate the TSV file with car make names
    let names_tsv = sim
        .dataset(common_path_prefix, &vecsim::DatasetName::cars)
        .expect("Failed to load Obj-Cars TSV")
        .as_tsv();
    progress_bar.finish();

    // Parse and validate the TSV file with car make names
    let names_tsv = sim
        .dataset(common_path_prefix, &vecsim::DatasetName::cartridges)
        .expect("Failed to load cartridge TSV")
        .as_tsv();
    progress_bar.finish();

    // Parse and validate the TSV file with utlity names
    let names_tsv = sim
        .dataset(common_path_prefix, &vecsim::DatasetName::utilities)
        .expect("Failed to load utilities TSV")
        .as_tsv();
    progress_bar.finish();

    // Parse and validate the TSV file with gui names
    let names_tsv = sim
        .dataset(common_path_prefix, &vecsim::DatasetName::gui)
        .expect("Failed to load gui TSV")
        .as_tsv();
    progress_bar.finish();

    // Parse and validate the TSV file with UI names
    let names_tsv = sim
        .dataset(common_path_prefix, &vecsim::DatasetName::ui)
        .expect("Failed to load ui TSV")

    // Parse and validate the TSV file with dozen names
    let names_tsv = sim
        .dataset(common_path_prefix, &vecsim::DatasetName::dozen)
        .expect("Failed to load dozen TSV")
        .as_tsv();
    progress_bar.finish();
}

//! Test correlation will be performed for mutually exclusive classes
fn non_overlapping_strategy<G>(criterion: &mut criterion::Criterion, sim: IntersectMany<G>) where
    G: AsRef<[u8]> + Clone + FromIterator + BoundAsRef,
{
    criterion.bench_function(
        "non-overlapping_parse",
        |b| b.iter(|| intersect(&mut criterion::Criterion::default(), sim.non_overlapping_parse::<G>())),
    );
}

criterion_group!(benches, non_overlapping_strategy, non_overlapping_extraction);
criterion_main!(benches);

//! Test variation will be performed for overlapping classes
fn overlapping_strategy<G>(criterion: &mut criterion::Criterion, sim: IntersectMany<G>) where
    G: AsRef<[u8]> + Clone + FromIterator + BoundAsRef,
{
    criterion.bench_function(
        "overlapping_parse",
        |b| b.iter(|| intersect(&mut criterion::Criterion::default(), sim.overlapping_parse::<G>())),
    );
}

criterion_group!(
    benches, // Add new benchmarks if any
    overlapping_strategy
);

fn overlap_disjointness_test<G>(sim: IntersectMany<G>) where
    G: AsRef<[u8]> + Clone + FromIterator + BoundAsRef,
{
    // Define the false positive threshold for overlapping class test
    // If plagiarism reports are very unlikely, set this threshold high.
    const F = 0.002;
    let all_cov = sim.covariance("coherent.parquet", vecsim::GaussianCovariancePreset::All);

    assert!(all_cov.strongly_invariant(&sim.common_dataset_path_prefix("coherent.parquet"), F));
}

fn non_overlap_disjointness_test<G>(sim: IntersectMany<G>) where
    G: AsRef<[u8]> + Clone + FromIterator + BoundAsRef,
{
    // Define the false positive threshold for overlapping class test
    // If plagiarism reports are very unlikely, set this threshold high.
    const F = 0.02;
    let all_cov = sim.covariance(&sim.common_dataset_path_prefix("common.parquet"), vecsim::GaussianCovariancePreset::All);

    assert!(all_cov.weakly_invariant(&sim.common_dataset_path_prefix("common.parquet"), F), "The datasets are expected to overlap.");
}

fn disjointness_test<G>(sim: IntersectMany<G>)

where
    G: AsRef<[u8]> + Clone + FromIterator + BoundAsRef,
{
    // Define the false positive assumption
    const TH = 0.98;

    let number_of_datasets_rounded2 = sim.images("common.parquet")/(sim.bubble_threshold() as usize);
    // 'number_of_datasets_rounded2' must be divisible by 2 under the assumption for the Gaussian distributions
    assert_eq!(number_of_datasets_rounded2 % 2, 0);

    let cov = sim.covariance(&sim.common_dataset_path_prefix("common.parquet"), vecsim::GaussianCovariancePreset::All);

    let datasets_per_group = sim.size(&sim.common_dataset_path_prefix("common.parquet"))/number_of_datasets_rounded2;

    // For overlapping strategies clone the dataset vectors and build them in the 'datasets_per_group' number
    let number_of_permutations = sim.bubbles(&sim.common_dataset_path_prefix("common.parquet"), vecsim::GaussianInputBounds::all(), 0.3);

    sim.throughput(&sim.common_dataset_path_prefix("common.parquet"));

    let algorithms: Vec<_> = Sim<PageHashing>::new(cov, TH, F)
        .bubbles(&sim.common_dataset_path_prefix("common.parquet"), vecsim::GaussianInputBounds::all(), 0.3)
        .num_bubbles(datasets_per_group)
        .num_permutations(number_of_permutations)
        .read(&sim.common_dataset_path_prefix("common.parquet"))
        .into_iter()
        .collect();

    let result = black_box(IntersectMany::new(algorithms.clone(), -1, dim_max(X::Array::all(), 0), number_of_datasets_rounded2, datasets_per_group, number_of_permutations));

    let real : f64 = Sim::throughput(
                                        &sim.common_dataset_path_prefix("common.parquet"),
                                        G,
                                        TH,
                                        F,
                                        std::mem::size_of::<u64>()/1024,
                                                1024,
                                            )
                        .through(&result);
    progress_bar.finish();

    assert!(real > TH - TH * TH/number_of_datasets_rounded2, "The overlap disjointness test failed!");
}

