[AttributeUsage(AttributeTargets.Property)]
public class ReadOnlyAttribute : JsonPropertyAttribute
{
    public ReadOnlyAttribute() : base(Required: false)
    {
    }
}

// Adjusted string entries with corresponding tags and correctness
public sealed class AnswerEntry
{
    [ReadOnly] // This property will only appear in the serialized JSON.
    public string Value { get; private set; }

    public string Tag { get; private set; }
    public bool IsCorrect { get; private set; }

    public AnswerEntry(string value, string tag, bool isCorrect)
    {
        Value = value;
        Tag = tag;
        IsCorrect = isCorrect;
    }
}

// Now, adjusting the QuizQuestion class to utilize AnswerEntry instances
public class QuizQuestion
{
